import { useEffect, useState } from "react";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import { Ticket, Clock, Send, Sparkles } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

type Props = { app?: AppHandle };

const FEED = [
  { id: 1, from: "Maya R.", subj: "Can't export invoices to CSV", pri: "high", sla: 252 },
  { id: 2, from: "Ops @ Northwind", subj: "Webhook retries failing since 9:40", pri: "urgent", sla: 96 },
  { id: 3, from: "Tomás V.", subj: "How do I add a teammate?", pri: "low", sla: 1380 },
  { id: 4, from: "Priya N.", subj: "Refund for duplicate charge", pri: "normal", sla: 610 },
  { id: 5, from: "Jonas K.", subj: "SSO login loops back to sign-in", pri: "high", sla: 188 },
  { id: 6, from: "Aiko S.", subj: "Where is my March statement?", pri: "normal", sla: 840 },
];
const PRI: Record<string, string> = {
  urgent: "bg-rose-500/15 text-rose-300 ring-rose-400/30",
  high: "bg-orange-500/15 text-orange-300 ring-orange-400/30",
  normal: "bg-sky-500/15 text-sky-300 ring-sky-400/30",
  low: "bg-slate-500/20 text-slate-300 ring-slate-400/20",
};
const REPLY = "Hi Maya, thanks for flagging this. I've re-run the export on our side and the CSV is on its way to your inbox now. Sorry for the wait!";

function clock(sec: number) {
  const s = Math.max(0, sec);
  const m = Math.floor(s / 60);
  return String(m).padStart(2, "0") + ":" + String(s % 60).padStart(2, "0");
}

function GoogleMark() {
  return (
    <svg width="18" height="18" viewBox="0 0 48 48" aria-hidden="true">
      <path fill="#EA4335" d="M24 9.5c3.5 0 6.6 1.2 9.1 3.6l6.8-6.8C35.8 2.4 30.3 0 24 0 14.6 0 6.5 5.4 2.6 13.2l7.9 6.1C12.4 13.6 17.7 9.5 24 9.5z" />
      <path fill="#4285F4" d="M46.5 24.5c0-1.6-.1-3.1-.4-4.5H24v9h12.7c-.6 3-2.3 5.5-4.8 7.2l7.5 5.8c4.4-4.1 7.1-10.1 7.1-17.5z" />
      <path fill="#FBBC05" d="M10.5 28.7c-.5-1.5-.8-3.1-.8-4.7s.3-3.2.8-4.7l-7.9-6.1C.9 16.4 0 20.1 0 24s.9 7.6 2.6 10.8l7.9-6.1z" />
      <path fill="#34A853" d="M24 48c6.5 0 11.9-2.1 15.9-5.8l-7.5-5.8c-2.1 1.4-4.8 2.3-8.4 2.3-6.3 0-11.6-4.1-13.5-9.8l-7.9 6.1C6.5 42.6 14.6 48 24 48z" />
    </svg>
  );
}

function LiveInbox({ compact }: { compact: boolean }) {
  const reduce = useReducedMotion();
  const [tick, setTick] = useState(0);
  const [chars, setChars] = useState(reduce ? REPLY.length : 0);

  useEffect(() => {
    if (reduce) return;
    const t = setInterval(() => setTick((v) => v + 1), 2200);
    return () => clearInterval(t);
  }, [reduce]);
  useEffect(() => {
    if (reduce) return;
    const t = setInterval(() => setChars((c) => (c >= REPLY.length + 30 ? 0 : c + 1)), 90);
    return () => clearInterval(t);
  }, [reduce]);

  const count = compact ? 2 : 4;
  const shown = Array.from({ length: count }, (_, i) => {
    const n = tick - i;
    return { ...FEED[((n % FEED.length) + FEED.length) % FEED.length], key: n };
  });
  const elapsed = tick * 2;

  return (
    <div className="w-full rounded-3xl border border-white/10 bg-slate-900/80 p-3 shadow-2xl shadow-sky-950/40 backdrop-blur sm:p-4" aria-hidden="true">
      <div className="mb-3 flex items-center justify-between px-1">
        <div className="flex items-center gap-2 text-sm font-semibold text-white">
          <span className="relative flex h-2 w-2">
            <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-emerald-400 opacity-70" />
            <span className="relative inline-flex h-2 w-2 rounded-full bg-emerald-400" />
          </span>
          Live queue
        </div>
        <div className="text-[11px] text-slate-400">support@acme</div>
      </div>
      <div className="space-y-2 overflow-hidden">
        <AnimatePresence initial={false} mode="popLayout">
          {shown.map((t, i) => {
            const left = t.sla - elapsed - i * 7;
            const hot = left < 120;
            return (
              <motion.div
                key={t.key}
                layout={!reduce}
                initial={reduce ? false : { opacity: 0, y: -28, scale: 0.97 }}
                animate={{ opacity: 1 - i * 0.12, y: 0, scale: 1 }}
                exit={reduce ? undefined : { opacity: 0, scale: 0.96 }}
                transition={{ type: "spring", stiffness: 380, damping: 30 }}
                className="flex items-center justify-between gap-3 rounded-2xl border border-white/10 bg-white/5 px-3.5 py-2.5"
              >
                <div className="min-w-0">
                  <div className="truncate text-[13px] font-semibold text-white">{t.subj}</div>
                  <div className="mt-0.5 flex items-center gap-2 text-[11px] text-slate-400">
                    <span className="truncate">{t.from}</span>
                    <span className={"rounded px-1.5 py-px text-[9px] font-bold uppercase ring-1 " + PRI[t.pri]}>{t.pri}</span>
                  </div>
                </div>
                <span className={"flex shrink-0 items-center gap-1 rounded-full px-2 py-0.5 font-mono text-[11px] font-semibold tabular-nums ring-1 " + (hot ? "bg-rose-500/15 text-rose-300 ring-rose-400/40" : "bg-emerald-500/10 text-emerald-300 ring-emerald-400/30")}>
                  <Clock size={11} />
                  {clock(left)}
                </span>
              </motion.div>
            );
          })}
        </AnimatePresence>
      </div>
      {!compact && (
        <div className="mt-3 rounded-2xl border border-sky-400/30 bg-sky-500/10 p-3">
          <div className="mb-1.5 flex items-center gap-1.5 text-[11px] font-semibold text-sky-300">
            <Sparkles size={12} /> Suggested reply
          </div>
          <div className="min-h-[56px] text-[13px] leading-relaxed text-slate-100">
            {REPLY.slice(0, chars)}
            <span className="ml-0.5 inline-block h-3.5 w-[2px] translate-y-0.5 animate-pulse bg-sky-300" />
          </div>
          <div className="mt-2 flex justify-end">
            <span className="flex items-center gap-1 rounded-lg bg-sky-500 px-2.5 py-1 text-[11px] font-semibold text-white">
              <Send size={11} /> Send
            </span>
          </div>
        </div>
      )}
    </div>
  );
}

export default function RelayLogin({ app }: Props) {
  const reduce = useReducedMotion();
  const auth = app?.auth;
  const mode = auth?.mode === "signup" ? "up" : "in";
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const providers = auth?.providers ?? [];

  const flip = () => {
    setError("");
    auth?.setMode(mode === "in" ? "signup" : "login");
  };

  const submit = async () => {
    if (!auth) return;
    setBusy(true);
    setError("");
    try {
      if (mode === "in") await auth.signIn(email, password);
      else await auth.signUp({ name, email, password });
    } catch (e) {
      setError(e instanceof Error ? e.message : "Something went wrong");
    }
    setBusy(false);
  };
  const social = async (p: string) => {
    setError("");
    try {
      await auth?.startProvider(p);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Could not start sign-in");
    }
  };

  const input =
    "w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-[15px] text-slate-900 outline-none transition focus:border-sky-500 focus:ring-4 focus:ring-sky-500/15";

  return (
    <div className="relative min-h-screen w-full overflow-hidden bg-slate-950 text-slate-900 [&_h1]:!font-sans [&_h2]:!font-sans [&_h3]:!font-sans">
      <div className="pointer-events-none absolute inset-0 bg-[radial-gradient(55%_45%_at_85%_20%,rgba(14,165,233,0.35),transparent),radial-gradient(40%_40%_at_10%_100%,rgba(56,189,248,0.18),transparent)]" />
      <div className="pointer-events-none absolute inset-0 opacity-[0.07] [background-image:linear-gradient(#fff_1px,transparent_1px),linear-gradient(90deg,#fff_1px,transparent_1px)] [background-size:40px_40px]" />

      <div className="relative mx-auto flex min-h-screen max-w-[1280px] flex-col px-4 py-5 lg:flex-row lg:items-center lg:gap-16 lg:px-10 lg:py-10">
        <div className="mb-4 lg:hidden">
          <div className="mb-3 flex items-center gap-2 text-lg font-bold tracking-tight text-white">
            <span className="grid h-8 w-8 place-items-center rounded-lg bg-sky-500 shadow-lg shadow-sky-500/40">
              <Ticket size={17} className="text-white" />
            </span>
            Relay
          </div>
          <LiveInbox compact />
        </div>

        <motion.div
          initial={reduce ? false : { opacity: 0, x: -24 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ type: "spring", stiffness: 160, damping: 22 }}
          className="w-full lg:max-w-[420px] lg:shrink-0"
        >
          <div className="mb-8 hidden items-center gap-2.5 text-xl font-bold tracking-tight text-white lg:flex">
            <span className="grid h-9 w-9 place-items-center rounded-xl bg-sky-500 shadow-lg shadow-sky-500/40">
              <Ticket size={20} className="text-white" />
            </span>
            Relay
          </div>
          <div className="rounded-3xl bg-white p-6 shadow-2xl shadow-black/30 sm:p-8">
            <h2 className="text-2xl font-bold tracking-tight">{mode === "in" ? "Welcome back" : "Create your account"}</h2>
            <p className="mt-1.5 text-sm text-slate-500">
              {mode === "in" ? "Sign in to your support desk." : "Sign up as a customer to open tickets."}
            </p>

            <div className="mt-6 space-y-4">
              <AnimatePresence initial={false}>
                {mode === "up" && (
                  <motion.div key="name" initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden">
                    <label htmlFor="relay-name" className="mb-1.5 block text-sm font-medium text-slate-700">Full name</label>
                    <input id="relay-name" aria-label="Full name" className={input} value={name} onChange={(e) => setName(e.target.value)} placeholder="Ada Lovelace" />
                  </motion.div>
                )}
              </AnimatePresence>
              <div>
                <label htmlFor="relay-email" className="mb-1.5 block text-sm font-medium text-slate-700">Email</label>
                <input id="relay-email" type="email" aria-label="Email" className={input} value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@company.com" autoComplete="email" />
              </div>
              <div>
                <label htmlFor="relay-password" className="mb-1.5 block text-sm font-medium text-slate-700">Password</label>
                <input id="relay-password" type="password" aria-label="Password" className={input} value={password} onChange={(e) => setPassword(e.target.value)} placeholder="••••••••" autoComplete={mode === "in" ? "current-password" : "new-password"} />
              </div>
              <AnimatePresence>
                {error && (
                  <motion.p initial={{ opacity: 0, y: -4 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="rounded-lg bg-rose-50 px-3 py-2 text-sm text-rose-700" role="alert">
                    {error}
                  </motion.p>
                )}
              </AnimatePresence>
              <motion.button
                whileTap={{ scale: 0.97 }}
                whileHover={{ y: -1 }}
                onClick={submit}
                disabled={busy}
                className="w-full rounded-xl bg-sky-500 px-4 py-3 text-[15px] font-semibold text-white shadow-lg shadow-sky-500/30 transition hover:bg-sky-600 disabled:opacity-60"
              >
                {mode === "in" ? "Sign in" : busy ? "Creating…" : "Create account"}
              </motion.button>
            </div>

            {providers.length > 0 && (
              <div className="mt-5">
                <div className="mb-4 flex items-center gap-3 text-xs uppercase tracking-wider text-slate-400">
                  <span className="h-px flex-1 bg-slate-200" /> or <span className="h-px flex-1 bg-slate-200" />
                </div>
                <div className="space-y-2.5">
                  {providers.map((p) => (
                    <motion.button
                      key={p.name}
                      whileTap={{ scale: 0.97 }}
                      onClick={() => social(p.name)}
                      className="flex w-full items-center justify-center gap-2.5 rounded-xl border border-slate-300 bg-white px-4 py-3 text-[15px] font-semibold text-slate-800 transition hover:bg-slate-50"
                    >
                      {p.name === "google" && <GoogleMark />}
                      Continue with {p.label}
                    </motion.button>
                  ))}
                </div>
              </div>
            )}

            {(auth?.canSignUp ?? true) && (
              <p className="mt-5 text-center text-sm text-slate-500">
                {mode === "in" ? "New to Relay?" : "Already have an account?"}{" "}
                <button className="font-semibold text-sky-600 hover:underline" onClick={flip}>
                  {mode === "in" ? "Create an account" : "Sign in"}
                </button>
              </p>
            )}
          </div>
        </motion.div>

        <motion.div
          initial={reduce ? false : { opacity: 0, x: 32 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ type: "spring", stiffness: 140, damping: 22, delay: 0.1 }}
          className="hidden min-w-0 flex-1 lg:block"
        >
          <h1 className="max-w-xl text-5xl font-bold leading-[1.05] tracking-tight text-white">
            Support that keeps its <span className="text-sky-400">promises.</span>
          </h1>
          <p className="mb-8 mt-4 max-w-md text-lg text-slate-300">Every ticket on the clock. Watch the queue move, the SLA tick, the reply write itself.</p>
          <div className="max-w-xl">
            <LiveInbox compact={false} />
          </div>
        </motion.div>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";
import { motion, AnimatePresence, LayoutGroup, useReducedMotion } from "motion/react";
import { Ticket, Plus, Send, ArrowLeft, Sparkles, X, LogOut, Inbox, CheckCircle, Star, MessageSquare } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

type R = Record<string, unknown>;
type Props = { app?: AppHandle };

const s = (v: unknown) => (v == null ? "" : String(v));
const HOURS: Record<string, number> = { urgent: 1, high: 4, normal: 8, low: 24 };
const STATUS: Record<string, { label: string; cls: string }> = {
  new: { label: "Received", cls: "bg-sky-50 text-sky-700 ring-sky-200" },
  open: { label: "In progress", cls: "bg-indigo-50 text-indigo-700 ring-indigo-200" },
  pending: { label: "Waiting on you", cls: "bg-amber-50 text-amber-700 ring-amber-200" },
  solved: { label: "Solved", cls: "bg-emerald-50 text-emerald-700 ring-emerald-200" },
};
const PRIORITY_DOT: Record<string, string> = { urgent: "bg-rose-500", high: "bg-orange-500", normal: "bg-sky-500", low: "bg-slate-400" };

function ago(iso: string, now: number) {
  const t = new Date(iso).getTime();
  if (!t || !now) return "";
  const m = Math.max(0, Math.round((now - t) / 60000));
  if (m < 1) return "just now";
  if (m < 60) return m + "m ago";
  if (m < 1440) return Math.round(m / 60) + "h ago";
  return Math.round(m / 1440) + "d ago";
}

function Stars({ value, onPick, size = 28, readOnly }: { value: number; onPick?: (n: number) => void; size?: number; readOnly?: boolean }) {
  const [hover, setHover] = useState(0);
  const reduce = useReducedMotion();
  const shown = hover || value;
  return (
    <div className="flex items-center gap-1" onMouseLeave={() => setHover(0)}>
      {[1, 2, 3, 4, 5].map((n) => (
        <motion.button
          key={n}
          aria-label={n + " star" + (n > 1 ? "s" : "")}
          disabled={readOnly}
          onMouseEnter={() => !readOnly && setHover(n)}
          onClick={() => onPick && onPick(n)}
          whileTap={reduce || readOnly ? undefined : { scale: 0.8 }}
          animate={n <= shown && !reduce ? { scale: [1, 1.25, 1], rotate: [0, -12, 0] } : { scale: 1 }}
          transition={{ type: "spring", stiffness: 400, damping: 12, delay: reduce ? 0 : n * 0.03 }}
          className="p-0.5"
        >
          <Star size={size} className={n <= shown ? "fill-amber-400 text-amber-400" : "text-slate-300"} />
        </motion.button>
      ))}
    </div>
  );
}

export default function CustomerPortal({ app }: Props) {
  const reduce = useReducedMotion();
  const [now, setNow] = useState(0);
  const [desktop, setDesktop] = useState(true);
  const [tab, setTab] = useState<"all" | "active" | "solved">("all");
  const [sel, setSel] = useState<string>("");
  const [composer, setComposer] = useState(false);
  const [toast, setToast] = useState("");

  useEffect(() => {
    setNow(Date.now());
    const t = setInterval(() => setNow(Date.now()), 30000);
    const mq = window.matchMedia("(min-width: 1024px)");
    const on = () => setDesktop(mq.matches);
    on();
    mq.addEventListener("change", on);
    return () => {
      clearInterval(t);
      mq.removeEventListener("change", on);
    };
  }, []);
  useEffect(() => {
    if (!app) return;
    const u1 = app.live("ticket");
    const u2 = app.live("message");
    return () => {
      u1();
      u2();
    };
  }, [app]);
  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(""), 3200);
    return () => clearTimeout(t);
  }, [toast]);

  const tickets: R[] = app ? (app.rows("ticket") as R[]) : [];
  const loading = app ? app.loading("ticket") : false;
  const sorted = useMemo(
    () => [...tickets].sort((a, b) => s(b.created_at).localeCompare(s(a.created_at))),
    [tickets]
  );
  const shown = sorted.filter((t) => (tab === "all" ? true : tab === "solved" ? s(t.status) === "solved" : s(t.status) !== "solved"));
  const active = sorted.filter((t) => s(t.status) !== "solved").length;
  const solved = sorted.length - active;
  const selected = sorted.find((t) => s(t.id) === sel) || (desktop ? shown[0] : undefined);
  const first = (app?.user.name || "there").split(" ")[0];

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 [&_h1]:!font-sans [&_h2]:!font-sans [&_h3]:!font-sans">
      <header className="sticky top-0 z-30 border-b border-slate-200/80 bg-white/80 backdrop-blur-xl">
        <div className="mx-auto flex h-16 max-w-6xl items-center justify-between px-4 sm:px-6">
          <div className="flex items-center gap-2.5 text-lg font-bold tracking-tight">
            <span className="grid h-8 w-8 place-items-center rounded-lg bg-sky-500 text-white shadow-md shadow-sky-500/30">
              <Ticket size={18} />
            </span>
            Relay
            <span className="ml-1 hidden rounded-md bg-slate-100 px-2 py-0.5 text-xs font-medium text-slate-500 sm:inline">Help centre</span>
          </div>
          <div className="flex items-center gap-2">
            <motion.button
              whileTap={{ scale: 0.95 }}
              whileHover={{ y: -1 }}
              onClick={() => setComposer(true)}
              className="flex items-center gap-1.5 rounded-xl bg-sky-500 px-3.5 py-2 text-sm font-semibold text-white shadow-md shadow-sky-500/30 hover:bg-sky-600"
            >
              <Plus size={16} /> New ticket
            </motion.button>
            <button aria-label="Sign out" onClick={() => app?.auth.signOut()} className="grid h-9 w-9 place-items-center rounded-xl text-slate-500 hover:bg-slate-100">
              <LogOut size={17} />
            </button>
          </div>
        </div>
      </header>

      <main className="mx-auto max-w-6xl px-4 pb-24 pt-6 sm:px-6">
        <motion.div initial={reduce ? false : { opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
          <div>
            <h1 className="font-sans text-2xl font-bold tracking-tight sm:text-3xl">Hi {first}, how can we help?</h1>
            <p className="mt-1 text-slate-500">Track your requests and chat with our support team.</p>
          </div>
          <div className="flex gap-3">
            {[
              { l: "In progress", v: active, c: "text-sky-600" },
              { l: "Solved", v: solved, c: "text-emerald-600" },
            ].map((x) => (
              <div key={x.l} className="min-w-[110px] rounded-2xl border border-slate-200 bg-white px-4 py-2.5 shadow-sm">
                <div className={"text-2xl font-bold tabular-nums " + x.c}>{x.v}</div>
                <div className="text-xs text-slate-500">{x.l}</div>
              </div>
            ))}
          </div>
        </motion.div>

        <div className="grid gap-5 lg:grid-cols-[380px_1fr]">
          <section>
            <LayoutGroup id="tabs">
              <div className="mb-3 flex gap-1 rounded-xl bg-slate-200/60 p-1">
                {(["all", "active", "solved"] as const).map((k) => (
                  <button key={k} onClick={() => setTab(k)} className="relative flex-1 rounded-lg px-3 py-1.5 text-sm font-medium capitalize">
                    {tab === k && <motion.span layoutId="tabpill" className="absolute inset-0 rounded-lg bg-white shadow-sm" transition={{ type: "spring", stiffness: 500, damping: 36 }} />}
                    <span className={"relative " + (tab === k ? "text-slate-900" : "text-slate-500")}>{k}</span>
                  </button>
                ))}
              </div>
            </LayoutGroup>
            <div className="space-y-2.5">
              {loading && sorted.length === 0 &&
                [0, 1, 2].map((i) => <div key={i} className="h-24 animate-pulse rounded-2xl bg-slate-200/70" />)}
              <AnimatePresence initial>
                {shown.map((t, i) => {
                  const st = STATUS[s(t.status) || "new"] || STATUS.new;
                  const on = selected && s(selected.id) === s(t.id);
                  return (
                    <motion.button
                      key={s(t.id)}
                      layout={!reduce}
                      initial={reduce ? false : { opacity: 0, y: 14 }}
                      animate={{ opacity: 1, y: 0 }}
                      exit={{ opacity: 0, scale: 0.96 }}
                      transition={{ type: "spring", stiffness: 300, damping: 28, delay: reduce ? 0 : Math.min(i, 8) * 0.04 }}
                      whileTap={{ scale: 0.985 }}
                      whileHover={{ y: -2 }}
                      onClick={() => setSel(s(t.id))}
                      className={"block w-full rounded-2xl border bg-white p-4 text-left shadow-[0_1px_2px_rgba(15,23,42,0.04),0_8px_24px_-12px_rgba(15,23,42,0.12)] transition-colors " + (on && desktop ? "border-sky-400 ring-4 ring-sky-500/10" : "border-slate-200")}
                    >
                      <div className="flex items-start justify-between gap-3">
                        <div className="line-clamp-2 text-[15px] font-semibold leading-snug">{s(t.subject)}</div>
                        <span className={"mt-0.5 h-2.5 w-2.5 shrink-0 rounded-full " + (PRIORITY_DOT[s(t.priority)] || "bg-slate-300")} />
                      </div>
                      <div className="mt-3 flex items-center justify-between">
                        <span className={"rounded-full px-2.5 py-0.5 text-xs font-medium ring-1 " + st.cls}>{st.label}</span>
                        <span className="text-xs text-slate-400">{ago(s(t.created_at), now)}</span>
                      </div>
                    </motion.button>
                  );
                })}
              </AnimatePresence>
              {!loading && shown.length === 0 && (
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="rounded-3xl border border-dashed border-slate-300 bg-white p-8 text-center">
                  <div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-sky-50 text-sky-500">
                    <Inbox size={26} />
                  </div>
                  <div className="mt-4 font-semibold">Nothing here yet</div>
                  <p className="mt-1 text-sm text-slate-500">Open a ticket and we will get back to you fast.</p>
                  <button onClick={() => setComposer(true)} className="mt-4 rounded-xl bg-sky-500 px-4 py-2 text-sm font-semibold text-white">
                    New ticket
                  </button>
                </motion.div>
              )}
            </div>
          </section>

          {desktop && (
            <section className="min-h-[520px]">
              {selected ? (
                <Thread key={s(selected.id)} app={app} ticket={selected} now={now} onToast={setToast} />
              ) : (
                <div className="grid h-full min-h-[420px] place-items-center rounded-3xl border border-dashed border-slate-300 bg-white/60 text-center text-slate-400">
                  <div>
                    <MessageSquare className="mx-auto mb-3" size={32} />
                    Select a ticket to see the conversation
                  </div>
                </div>
              )}
            </section>
          )}
        </div>
      </main>

      <AnimatePresence>
        {!desktop && selected && sel && (
          <motion.div
            key="sheet"
            initial={{ x: "100%" }}
            animate={{ x: 0 }}
            exit={{ x: "100%" }}
            transition={{ type: "spring", stiffness: 320, damping: 34 }}
            className="fixed inset-0 z-40 flex flex-col bg-slate-50"
          >
            <Thread app={app} ticket={selected} now={now} onToast={setToast} onBack={() => setSel("")} />
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>{composer && <Composer app={app} onClose={() => setComposer(false)} onDone={(id) => { setComposer(false); setSel(id); setToast("Ticket sent — we're on it"); }} />}</AnimatePresence>

      <AnimatePresence>
        {toast && (
          <motion.div
            initial={{ opacity: 0, y: 30, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 20 }}
            className="fixed bottom-5 left-1/2 z-[60] flex -translate-x-1/2 items-center gap-2 rounded-2xl bg-slate-900 px-4 py-3 text-sm font-medium text-white shadow-2xl"
          >
            <CheckCircle size={16} className="text-emerald-400" /> {toast}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

function Thread({ app, ticket, now, onToast, onBack }: { app?: AppHandle; ticket: R; now: number; onToast: (m: string) => void; onBack?: () => void }) {
  const reduce = useReducedMotion();
  const id = s(ticket.id);
  const status = s(ticket.status) || "new";
  const msgs = (app ? (app.rows("message") as R[]) : [])
    .filter((m) => s(m.ticket_id) === id)
    .sort((a, b) => (s(a.at) || s(a.created_at)).localeCompare(s(b.at) || s(b.created_at)));
  const [text, setText] = useState("");
  const [sending, setSending] = useState(false);
  const [rating, setRating] = useState(0);
  const [comment, setComment] = useState("");
  const csat = Number(ticket.csat) || 0;
  const st = STATUS[status] || STATUS.new;

  const send = async () => {
    if (!app || !text.trim()) return;
    setSending(true);
    try {
      await app.create("message", { ticket_id: id, author_name: app.user.name, author_role: "customer", body: text.trim(), at: new Date().toISOString() });
      setText("");
    } catch (e) {
      onToast(e instanceof Error ? e.message : "Could not send");
    }
    setSending(false);
  };
  const rate = async () => {
    if (!app || !rating) return;
    try {
      await app.update("ticket", id, { csat: rating, csat_comment: comment });
      onToast("Thanks for the feedback!");
    } catch (e) {
      onToast(e instanceof Error ? e.message : "Could not save rating");
    }
  };

  return (
    <div className="flex h-full min-h-0 flex-1 flex-col overflow-hidden bg-white lg:rounded-3xl lg:border lg:border-slate-200 lg:shadow-[0_1px_2px_rgba(15,23,42,0.04),0_16px_40px_-16px_rgba(15,23,42,0.15)]">
      <div className="flex items-start gap-3 border-b border-slate-100 p-4 sm:p-5">
        {onBack && (
          <button aria-label="Back" onClick={onBack} className="mt-0.5 grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-slate-100">
            <ArrowLeft size={18} />
          </button>
        )}
        <div className="min-w-0 flex-1">
          <h2 className="font-sans text-lg font-bold leading-snug">{s(ticket.subject)}</h2>
          <div className="mt-2 flex flex-wrap items-center gap-2 text-xs">
            <span className={"rounded-full px-2.5 py-0.5 font-medium ring-1 " + st.cls}>{st.label}</span>
            <span className="text-slate-400">Opened {ago(s(ticket.created_at), now)}</span>
          </div>
        </div>
      </div>

      <div className="flex-1 space-y-3 overflow-y-auto bg-slate-50/60 p-4 sm:p-5">
        <Bubble mine name="You" body={s(ticket.body)} time={ago(s(ticket.created_at), now)} i={0} />
        <AnimatePresence initial={false}>
          {msgs.map((m, i) => (
            <Bubble key={s(m.id)} mine={s(m.author_role) === "customer"} name={s(m.author_role) === "customer" ? "You" : s(m.author_name)} body={s(m.body)} time={ago(s(m.at) || s(m.created_at), now)} i={i + 1} />
          ))}
        </AnimatePresence>

        {status === "solved" && (
          <motion.div
            initial={reduce ? false : { opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="rounded-2xl border border-emerald-200 bg-gradient-to-br from-emerald-50 to-white p-5 text-center"
          >
            <CheckCircle className="mx-auto text-emerald-500" size={28} />
            <div className="mt-2 font-semibold text-emerald-900">This ticket was marked solved</div>
            {csat ? (
              <div className="mt-3 flex flex-col items-center gap-1">
                <Stars value={csat} readOnly size={26} />
                <div className="text-sm text-slate-500">Thanks for rating us{s(ticket.csat_comment) ? ` — “${s(ticket.csat_comment)}”` : ""}</div>
              </div>
            ) : (
              <div className="mt-3 flex flex-col items-center gap-3">
                <div className="text-sm text-slate-600">How was your experience?</div>
                <Stars value={rating} onPick={setRating} size={34} />
                <AnimatePresence>
                  {rating > 0 && (
                    <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: "auto" }} exit={{ opacity: 0, height: 0 }} className="w-full max-w-sm space-y-2 overflow-hidden">
                      <textarea aria-label="Feedback" value={comment} onChange={(e) => setComment(e.target.value)} rows={2} placeholder="Anything we could do better? (optional)" className="w-full resize-none rounded-xl border border-slate-200 bg-white p-3 text-sm outline-none focus:border-sky-400" />
                      <motion.button whileTap={{ scale: 0.96 }} onClick={rate} className="w-full rounded-xl bg-sky-500 py-2.5 text-sm font-semibold text-white">
                        Submit rating
                      </motion.button>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            )}
          </motion.div>
        )}
      </div>

      <div className="border-t border-slate-100 bg-white p-3 sm:p-4">
        <div className="flex items-end gap-2">
          <textarea
            aria-label="Reply"
            value={text}
            onChange={(e) => setText(e.target.value)}
            rows={1}
            placeholder={status === "solved" ? "Reply to reopen the conversation…" : "Write a reply…"}
            className="max-h-32 min-h-[44px] flex-1 resize-none rounded-xl border border-slate-200 bg-slate-50 px-3.5 py-2.5 text-[15px] outline-none focus:border-sky-400 focus:bg-white"
          />
          <motion.button whileTap={{ scale: 0.9 }} disabled={sending || !text.trim()} onClick={send} aria-label="Send" className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-sky-500 text-white shadow-md shadow-sky-500/30 disabled:opacity-40">
            <Send size={18} />
          </motion.button>
        </div>
      </div>
    </div>
  );
}

function Bubble({ mine, name, body, time, i }: { mine: boolean; name: string; body: string; time: string; i: number }) {
  const reduce = useReducedMotion();
  return (
    <motion.div
      layout={!reduce}
      initial={reduce ? false : { opacity: 0, y: 12, scale: 0.97 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      transition={{ type: "spring", stiffness: 320, damping: 26, delay: reduce ? 0 : Math.min(i, 6) * 0.04 }}
      className={"flex " + (mine ? "justify-end" : "justify-start")}
    >
      <div className={"max-w-[86%] rounded-2xl px-4 py-2.5 shadow-sm " + (mine ? "rounded-br-md bg-sky-500 text-white" : "rounded-bl-md border border-slate-200 bg-white")}>
        <div className={"mb-0.5 text-[11px] font-semibold " + (mine ? "text-sky-100" : "text-sky-600")}>{name}</div>
        <div className="whitespace-pre-wrap text-[15px] leading-relaxed">{body}</div>
        <div className={"mt-1 text-right text-[10px] " + (mine ? "text-sky-100" : "text-slate-400")}>{time}</div>
      </div>
