}

function Composer({ app, onClose, onDone }: { app?: AppHandle; onClose: () => void; onDone: (id: string) => void }) {
  const [subject, setSubject] = useState("");
  const [body, setBody] = useState("");
  const [priority, setPriority] = useState("normal");
  const [category, setCategory] = useState("other");
  const [busy, setBusy] = useState(false);
  const [ai, setAi] = useState(false);
  const [err, setErr] = useState("");

  const triage = async () => {
    if (!app || !body.trim()) return;
    setAi(true);
    setErr("");
    try {
      const out = await app.ai.ask(
        "Ticket subject: " + subject + "\nDescription: " + body + "\nReturn ONLY JSON like {\"priority\":\"low|normal|high|urgent\",\"category\":\"billing|bug|how_to|account|feature_request|other\"}.",
        { system: "You triage customer support tickets. Reply with compact JSON only.", maxTokens: 60 }
      );
      const m = out.match(/\{[^}]*\}/);
      if (m) {
        const j = JSON.parse(m[0]) as R;
        if (["low", "normal", "high", "urgent"].includes(s(j.priority))) setPriority(s(j.priority));
        if (["billing", "bug", "how_to", "account", "feature_request", "other"].includes(s(j.category))) setCategory(s(j.category));
      }
    } catch {
      setErr("AI triage is unavailable right now — pick a priority yourself.");
    }
    setAi(false);
  };

  const submit = async () => {
    if (!app || !subject.trim() || !body.trim()) {
      setErr("Add a subject and a description.");
      return;
    }
    setBusy(true);
    try {
      const row = await app.create("ticket", {
        subject: subject.trim(),
        body: body.trim(),
        priority,
        category,
        status: "new",
        from: app.user.email || null,
        customer_id: app.me("customer") || null,
        sla_due: new Date(Date.now() + (HOURS[priority] || 8) * 3600000).toISOString(),
        escalated: false,
      });
      onDone(s(row.id));
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Could not create ticket");
      setBusy(false);
    }
  };

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-50 flex items-end justify-center bg-slate-900/50 backdrop-blur-sm sm:items-center" onClick={onClose}>
      <motion.div
        initial={{ y: 80, opacity: 0, scale: 0.98 }}
        animate={{ y: 0, opacity: 1, scale: 1 }}
        exit={{ y: 80, opacity: 0 }}
        transition={{ type: "spring", stiffness: 340, damping: 30 }}
        onClick={(e) => e.stopPropagation()}
        className="max-h-[92vh] w-full max-w-lg overflow-y-auto rounded-t-3xl bg-white p-5 shadow-2xl sm:rounded-3xl sm:p-6"
      >
        <div className="mb-4 flex items-center justify-between">
          <h3 className="font-sans text-xl font-bold">New ticket</h3>
          <button aria-label="Close" onClick={onClose} className="grid h-9 w-9 place-items-center rounded-xl hover:bg-slate-100">
            <X size={18} />
          </button>
        </div>
        <div className="space-y-4">
          <div>
            <label htmlFor="t-subject" className="mb-1.5 block text-sm font-medium text-slate-700">Subject</label>
            <input id="t-subject" value={subject} onChange={(e) => setSubject(e.target.value)} placeholder="What do you need help with?" className="w-full rounded-xl border border-slate-200 px-3.5 py-2.5 outline-none focus:border-sky-400 focus:ring-4 focus:ring-sky-500/10" />
          </div>
          <div>
            <label htmlFor="t-body" className="mb-1.5 block text-sm font-medium text-slate-700">Description</label>
            <textarea id="t-body" value={body} onChange={(e) => setBody(e.target.value)} rows={4} placeholder="Tell us what happened, and what you expected." className="w-full resize-none rounded-xl border border-slate-200 px-3.5 py-2.5 outline-none focus:border-sky-400 focus:ring-4 focus:ring-sky-500/10" />
          </div>
          <div>
            <div className="mb-1.5 flex items-center justify-between">
              <span className="text-sm font-medium text-slate-700">Priority</span>
              <button onClick={triage} disabled={ai || !body.trim()} className="flex items-center gap-1 rounded-lg bg-sky-50 px-2.5 py-1 text-xs font-semibold text-sky-700 disabled:opacity-40">
                <Sparkles size={13} className={ai ? "animate-spin" : ""} /> {ai ? "Thinking…" : "Suggest with AI"}
              </button>
            </div>
            <div className="grid grid-cols-4 gap-2">
              {["low", "normal", "high", "urgent"].map((p) => (
                <motion.button key={p} whileTap={{ scale: 0.94 }} onClick={() => setPriority(p)} className={"rounded-xl border px-2 py-2 text-sm font-medium capitalize transition-colors " + (priority === p ? "border-sky-500 bg-sky-50 text-sky-700" : "border-slate-200 text-slate-600")}>
                  {p}
                </motion.button>
              ))}
            </div>
            <div className="mt-2 text-xs text-slate-500">Category: <span className="font-medium capitalize text-slate-700">{category.replace("_", " ")}</span> · we reply within {HOURS[priority]}h</div>
          </div>
          {err && <div className="rounded-lg bg-rose-50 px-3 py-2 text-sm text-rose-700">{err}</div>}
          <motion.button whileTap={{ scale: 0.97 }} onClick={submit} disabled={busy} className="w-full rounded-xl bg-sky-500 py-3 font-semibold text-white shadow-lg shadow-sky-500/30 disabled:opacity-60">
            {busy ? "Sending…" : "Send ticket"}
          </motion.button>
        </div>
      </motion.div>
    </motion.div>
  );
}

