import type { AppHandle } from "@app/kit/primitives";

type R = Record<string, unknown>;
type Props = { app?: AppHandle };

const s = (v: unknown) => (v == null ? "" : String(v));
const FLOW = ["new", "open", "pending", "solved"];
const PRI: Record<string, { cls: string; dot: string }> = {
  urgent: { cls: "bg-rose-50 text-rose-700 ring-rose-200", dot: "bg-rose-500" },
  high: { cls: "bg-orange-50 text-orange-700 ring-orange-200", dot: "bg-orange-500" },
  normal: { cls: "bg-sky-50 text-sky-700 ring-sky-200", dot: "bg-sky-500" },
  low: { cls: "bg-slate-100 text-slate-600 ring-slate-200", dot: "bg-slate-400" },
};
const ST: Record<string, string> = {
  new: "bg-sky-500",
  open: "bg-indigo-500",
  pending: "bg-amber-500",
  solved: "bg-emerald-500",
};

function dur(ms: number) {
  const m = Math.floor(Math.abs(ms) / 60000);
  if (m < 60) return m + "m";
  const h = Math.floor(m / 60);
  if (h < 24) return h + "h " + (m % 60) + "m";
  return Math.floor(h / 24) + "d " + (h % 24) + "h";
}
function slaInfo(t: R, now: number) {
  if (s(t.status) === "solved") return { label: "Solved", cls: "bg-slate-100 text-slate-500 ring-slate-200", level: "done", ms: 0 };
  const due = new Date(s(t.sla_due)).getTime();
  if (!due || !now) return { label: "—", cls: "bg-slate-100 text-slate-500 ring-slate-200", level: "none", ms: 1e12 };
  const ms = due - now;
  if (ms < 0) return { label: "Breached " + dur(ms), cls: "bg-rose-50 text-rose-700 ring-rose-300", level: "red", ms };
  if (ms < 2 * 3600000) return { label: dur(ms) + " left", cls: "bg-amber-50 text-amber-700 ring-amber-300", level: "amber", ms };
  return { label: dur(ms) + " left", cls: "bg-emerald-50 text-emerald-700 ring-emerald-300", level: "green", ms };
}
function ago(iso: string, now: number) {
  const t = new Date(iso).getTime();
  if (!t || !now) return "";
  const m = Math.max(0, Math.round((now - t) / 60000));
  if (m < 1) return "just now";
  if (m < 60) return m + "m ago";
  if (m < 1440) return Math.round(m / 60) + "h ago";
  return Math.round(m / 1440) + "d ago";
}

function SlaChip({ t, now }: { t: R; now: number }) {
  const i = slaInfo(t, now);
  return (
    <span className={"inline-flex items-center gap-1 whitespace-nowrap rounded-full px-2 py-0.5 text-[11px] font-semibold tabular-nums ring-1 " + i.cls}>
      {i.level === "red" ? (
        <span className="relative flex h-1.5 w-1.5">
          <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-rose-500 opacity-75" />
          <span className="relative inline-flex h-1.5 w-1.5 rounded-full bg-rose-500" />
        </span>
      ) : (
        <Clock size={11} />
      )}
      {i.label}
    </span>
  );
}

