export default function AgentInbox({ app }: Props) {
  const reduce = useReducedMotion();
  const [now, setNow] = useState(0);
  const [desktop, setDesktop] = useState(true);
  const [scope, setScope] = useState<"all" | "mine" | "unassigned">("all");
  const [stat, setStat] = useState("active");
  const [q, setQ] = useState("");
  const [sel, setSel] = useState("");
  const [toast, setToast] = useState("");

  useEffect(() => {
    setNow(Date.now());
    const t = setInterval(() => setNow(Date.now()), 20000);
    const mq = window.matchMedia("(min-width: 1024px)");
    const on = () => setDesktop(mq.matches);
    on();
    mq.addEventListener("change", on);
    return () => {
      clearInterval(t);
      mq.removeEventListener("change", on);
    };
  }, []);
  useEffect(() => {
    if (!app) return;
    const us = [app.live("ticket"), app.live("message"), app.live("note")];
    return () => us.forEach((u) => u());
  }, [app]);
  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(""), 3200);
    return () => clearTimeout(t);
  }, [toast]);

  const tickets: R[] = app ? (app.rows("ticket") as R[]) : [];
  const customers: R[] = app ? (app.rows("customer") as R[]) : [];
  const agents: R[] = app ? (app.rows("agent") as R[]) : [];
  const loading = app ? app.loading("ticket") : false;
  const meAgent = app ? app.me("agent") : undefined;

  const list = useMemo(() => {
    const needle = q.trim().toLowerCase();
    return tickets
      .filter((t) => {
        const status = s(t.status) || "new";
        if (stat === "active" ? status === "solved" : stat !== "all" && status !== stat) return false;
        if (scope === "mine" && s(t.assignee_id) !== (meAgent || "-")) return false;
        if (scope === "unassigned" && s(t.assignee_id)) return false;
        if (needle && !(s(t.subject) + " " + s(t.body)).toLowerCase().includes(needle)) return false;
        return true;
      })
      .sort((a, b) => {
        const as = s(a.status) === "solved" ? 1 : 0;
        const bs = s(b.status) === "solved" ? 1 : 0;
        if (as !== bs) return as - bs;
        return (s(a.sla_due) || "9").localeCompare(s(b.sla_due) || "9");
      });
  }, [tickets, stat, scope, q, meAgent]);

  const open = tickets.filter((t) => s(t.status) !== "solved");
  const breaching = open.filter((t) => ["red", "amber"].includes(slaInfo(t, now).level)).length;
  const unassigned = open.filter((t) => !s(t.assignee_id)).length;
  const selected = tickets.find((t) => s(t.id) === sel) || (desktop ? list[0] : undefined);
  const custOf = (t: R) => customers.find((c) => s(c.id) === s(t.customer_id));
  const agentOf = (t: R) => agents.find((a) => s(a.id) === s(t.assignee_id));

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 lg:pl-[68px] [&_h1]:!font-sans [&_h2]:!font-sans [&_h3]:!font-sans">
      <Rail app={app} active="queue" />
      <MobileBar app={app} active="queue" />

      <div className="mx-auto flex max-w-[1500px] flex-col lg:h-screen">
        <div className="px-4 pb-3 pt-5 lg:px-6">
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div>
              <div className="flex items-center gap-2">
                <h1 className="font-sans text-2xl font-bold tracking-tight">Queue</h1>
                <span className="flex items-center gap-1 rounded-full bg-emerald-50 px-2 py-0.5 text-[11px] font-semibold text-emerald-700 ring-1 ring-emerald-200">
                  <CircleDot size={11} className="animate-pulse" /> Live
                </span>
              </div>
              <p className="text-sm text-slate-500">{app?.user.name ? "Signed in as " + app.user.name : "Support queue"}</p>
            </div>
            <div className="grid grid-cols-3 gap-2">
              {[
                { l: "Open", v: open.length, c: "text-slate-900" },
                { l: "At risk", v: breaching, c: "text-rose-600" },
                { l: "Unassigned", v: unassigned, c: "text-amber-600" },
              ].map((k) => (
                <div key={k.l} className="min-w-[84px] rounded-xl border border-slate-200 bg-white px-3 py-1.5 shadow-sm">
                  <motion.div key={k.v} initial={reduce ? false : { y: -8, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className={"text-xl font-bold tabular-nums leading-tight " + k.c}>
                    {k.v}
                  </motion.div>
                  <div className="text-[11px] text-slate-500">{k.l}</div>
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="grid min-h-0 flex-1 gap-4 px-4 pb-24 lg:grid-cols-[400px_1fr] lg:px-6 lg:pb-6">
          <section className="flex min-h-0 flex-col">
            <div className="relative mb-2.5">
              <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <input aria-label="Search tickets" value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search tickets" className="w-full rounded-xl border border-slate-200 bg-white py-2 pl-9 pr-3 text-sm outline-none focus:border-sky-400 focus:ring-4 focus:ring-sky-500/10" />
            </div>
            <LayoutGroup id="scope">
              <div className="mb-2 flex gap-1 rounded-xl bg-slate-200/60 p-1">
                {(["all", "mine", "unassigned"] as const).map((k) => (
                  <button key={k} onClick={() => setScope(k)} className="relative flex-1 rounded-lg py-1.5 text-[13px] font-medium capitalize">
                    {scope === k && <motion.span layoutId="scopepill" className="absolute inset-0 rounded-lg bg-white shadow-sm" transition={{ type: "spring", stiffness: 500, damping: 36 }} />}
                    <span className={"relative " + (scope === k ? "text-slate-900" : "text-slate-500")}>{k}</span>
                  </button>
                ))}
              </div>
            </LayoutGroup>
            <div className="mb-3 flex gap-1.5 overflow-x-auto pb-1">
              {["active", "new", "open", "pending", "solved", "all"].map((k) => (
                <button key={k} onClick={() => setStat(k)} className={"shrink-0 rounded-full px-3 py-1 text-xs font-semibold capitalize ring-1 transition-colors " + (stat === k ? "bg-slate-900 text-white ring-slate-900" : "bg-white text-slate-600 ring-slate-200 hover:ring-slate-300")}>
                  {k}
                </button>
              ))}
            </div>

            <div className="min-h-0 flex-1 space-y-2 lg:overflow-y-auto lg:pr-1">
              {loading && tickets.length === 0 && [0, 1, 2, 3].map((i) => <div key={i} className="h-24 animate-pulse rounded-2xl bg-slate-200/70" />)}
              <AnimatePresence initial>
                {list.map((t, i) => {
                  const on = selected && s(selected.id) === s(t.id);
                  const c = custOf(t);
                  const p = PRI[s(t.priority) || "normal"] || PRI.normal;
                  const ag = agentOf(t);
                  return (
                    <motion.button
                      key={s(t.id)}
                      layout={!reduce}
                      initial={reduce ? false : { opacity: 0, x: -48 }}
                      animate={{ opacity: 1, x: 0 }}
                      exit={{ opacity: 0, x: 40 }}
                      transition={{ type: "spring", stiffness: 340, damping: 30, delay: reduce ? 0 : Math.min(i, 8) * 0.035 }}
                      whileTap={{ scale: 0.985 }}
                      onClick={() => setSel(s(t.id))}
                      className={"relative block w-full overflow-hidden rounded-2xl border bg-white p-3.5 pl-4 text-left shadow-[0_1px_2px_rgba(15,23,42,0.04),0_6px_18px_-10px_rgba(15,23,42,0.14)] " + (on && desktop ? "border-sky-400 ring-4 ring-sky-500/10" : "border-slate-200 hover:border-slate-300")}
                    >
                      <span className={"absolute inset-y-0 left-0 w-1 " + p.dot} />
                      <div className="flex items-start justify-between gap-2">
                        <div className="line-clamp-2 text-[14px] font-semibold leading-snug">{s(t.subject)}</div>
                        <SlaChip t={t} now={now} />
                      </div>
                      <div className="mt-2 flex items-center justify-between gap-2 text-xs text-slate-500">
                        <div className="flex min-w-0 items-center gap-2">
                          <span className={"h-2 w-2 shrink-0 rounded-full " + (ST[s(t.status) || "new"] || "bg-slate-400")} />
                          <span className="capitalize">{s(t.status) || "new"}</span>
                          <span className="truncate text-slate-400">· {c ? s(c.name) : s(t.from) || "Unknown"}</span>
                        </div>
                        <div className="flex shrink-0 items-center gap-1.5">
                          <span className={"rounded-md px-1.5 py-0.5 text-[10px] font-bold uppercase ring-1 " + p.cls}>{s(t.priority) || "normal"}</span>
                          <span className="grid h-5 w-5 place-items-center rounded-full bg-slate-100 text-[9px] font-bold text-slate-600">{ag ? s(ag.name).split(" ").map((x) => x[0]).join("") : "–"}</span>
                        </div>
                      </div>
                    </motion.button>
                  );
                })}
              </AnimatePresence>
              {!loading && list.length === 0 && (
                <div className="rounded-3xl border border-dashed border-slate-300 bg-white p-8 text-center">
                  <div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-emerald-50 text-emerald-500">
                    <CheckCircle size={26} />
                  </div>
                  <div className="mt-3 font-semibold">Inbox zero</div>
                  <p className="mt-1 text-sm text-slate-500">No tickets match these filters. Nicely done.</p>
                </div>
              )}
            </div>
          </section>

          {desktop && (
            <section className="min-h-0">
              {selected ? (
                <Detail key={s(selected.id)} app={app} ticket={selected} customer={custOf(selected)} agent={agentOf(selected)} now={now} onToast={setToast} meAgent={meAgent} />
              ) : (
                <div className="grid h-full min-h-[360px] place-items-center rounded-3xl border border-dashed border-slate-300 bg-white/60 text-slate-400">Select a ticket</div>
              )}
            </section>
          )}
        </div>
      </div>

      <AnimatePresence>
        {!desktop && selected && sel && (
          <motion.div key="sheet" initial={{ x: "100%" }} animate={{ x: 0 }} exit={{ x: "100%" }} transition={{ type: "spring", stiffness: 320, damping: 34 }} className="fixed inset-0 z-40 flex flex-col bg-slate-50">
            <Detail app={app} ticket={selected} customer={custOf(selected)} agent={agentOf(selected)} now={now} onToast={setToast} meAgent={meAgent} onBack={() => setSel("")} />
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {toast && (
          <motion.div initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 20 }} className="fixed bottom-5 left-1/2 z-[60] max-w-[90vw] -translate-x-1/2 rounded-2xl bg-slate-900 px-4 py-3 text-sm font-medium text-white shadow-2xl">
            {toast}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

function Detail({ app, ticket, customer, agent, now, onToast, meAgent, onBack }: { app?: AppHandle; ticket: R; customer?: R; agent?: R; now: number; onToast: (m: string) => void; meAgent?: string; onBack?: () => void }) {
  const reduce = useReducedMotion();
  const id = s(ticket.id);
  const status = s(ticket.status) || "new";
  const [mode, setMode] = useState<"reply" | "note">("reply");
  const [text, setText] = useState("");
  const [busy, setBusy] = useState(false);
  const [suggesting, setSuggesting] = useState(false);

  const msgs: R[] = (app ? (app.rows("message") as R[]) : []).filter((m) => s(m.ticket_id) === id).map((m): R => ({ ...m, kind: "msg" }));
  const notes: R[] = (app ? (app.rows("note") as R[]) : []).filter((m) => s(m.ticket_id) === id).map((m): R => ({ ...m, kind: "note" }));
  const thread: R[] = [...msgs, ...notes].sort((a, b) => (s(a.at) || s(a.created_at)).localeCompare(s(b.at) || s(b.created_at)));
  const p = PRI[s(ticket.priority) || "normal"] || PRI.normal;

  const setStatus = async (to: string) => {
    if (!app || to === status) return;
    try {
      try {
        await app.update("ticket", id, { status: to });
      } catch (e1) {
        if (to === "solved") throw e1;
        await app.transition("ticket", id, "status", to);
      }
      onToast("Status → " + to);
    } catch (e) {
      onToast(e instanceof Error ? e.message : "Could not change status");
    }
  };
  const assignMe = async () => {
    if (!app || !meAgent) return;
    try {
      await app.update("ticket", id, { assignee_id: meAgent, ...(status === "new" ? { status: "open" } : {}) });
      onToast("Assigned to you");
    } catch (e) {
      onToast(e instanceof Error ? e.message : "Could not assign");
    }
  };
  const send = async () => {
    if (!app || !text.trim()) return;
    setBusy(true);
    try {
      if (mode === "reply") {
        await app.create("message", { ticket_id: id, author_name: app.user.name, author_role: "agent", body: text.trim(), at: new Date().toISOString(), customer_id: s(ticket.customer_id) || null });
        const patch: R = {};
        if (!s(ticket.assignee_id) && meAgent) patch.assignee_id = meAgent;
        if (status === "new") patch.status = "open";
        if (Object.keys(patch).length) await app.update("ticket", id, patch);
        onToast("Reply sent · customer notified");
      } else {
        await app.create("note", { ticket_id: id, author_name: app.user.name, body: text.trim(), at: new Date().toISOString() });
        onToast("Internal note added");
      }
      setText("");
    } catch (e) {
      onToast(e instanceof Error ? e.message : "Could not send");
    }
    setBusy(false);
  };
  const suggest = async () => {
    if (!app) return;
    setSuggesting(true);
    try {
      const convo = thread.filter((m) => m.kind === "msg").slice(-6).map((m) => s(m.author_role) + ": " + s(m.body)).join("\n");
      const out = await app.ai.ask(
        "Ticket: " + s(ticket.subject) + "\nCustomer wrote: " + s(ticket.body) + "\nConversation so far:\n" + convo + "\n\nWrite the agent's next reply (max 90 words). Acknowledge the customer's issue, give a concrete next step, no placeholders.",
        { system: "You are a warm, concise senior support agent at Relay. Write only the reply text, signed with the first name " + (app.user.name || "").split(" ")[0] + ".", maxTokens: 220 }
      );
      setMode("reply");
      setText(out.trim());
    } catch {
      onToast("AI is resting right now, try again soon");
    }
    setSuggesting(false);
  };

  return (
    <div className="flex h-full min-h-0 flex-1 flex-col overflow-hidden bg-white lg:rounded-3xl lg:border lg:border-slate-200 lg:shadow-[0_1px_2px_rgba(15,23,42,0.04),0_16px_40px_-16px_rgba(15,23,42,0.15)]">
      <div className="border-b border-slate-100 p-4 sm:p-5">
        <div className="flex items-start gap-3">
          {onBack && (
            <button aria-label="Back" onClick={onBack} className="mt-0.5 grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-slate-100">
              <ArrowLeft size={18} />
            </button>
          )}
          <div className="min-w-0 flex-1">
            <h2 className="font-sans text-lg font-bold leading-snug">{s(ticket.subject)}</h2>
            <div className="mt-2 flex flex-wrap items-center gap-2">
              <SlaChip t={ticket} now={now} />
              <span className={"rounded-md px-1.5 py-0.5 text-[10px] font-bold uppercase ring-1 " + p.cls}>{s(ticket.priority) || "normal"}</span>
              <span className="rounded-md bg-slate-100 px-1.5 py-0.5 text-[10px] font-semibold capitalize text-slate-600">{s(ticket.category).replace("_", " ") || "other"}</span>
              {ticket.escalated === true && <span className="rounded-md bg-rose-100 px-1.5 py-0.5 text-[10px] font-bold uppercase text-rose-700">Escalated</span>}
            </div>
          </div>
        </div>
        <div className="mt-4 flex flex-wrap items-center justify-between gap-3">
          <div className="flex items-center gap-2.5">
            <div className="h-9 w-9 overflow-hidden rounded-full bg-slate-200">
              {customer && (s(customer.avatar).startsWith("http") || s(customer.avatar).startsWith("/")) ? <img src={s(customer.avatar)} alt="" className="h-full w-full object-cover" /> : <div className="grid h-full w-full place-items-center text-xs font-bold text-slate-500">{customer ? s(customer.name).slice(0, 1) : "?"}</div>}
            </div>
            <div className="leading-tight">
              <div className="text-sm font-semibold">{customer ? s(customer.name) : s(ticket.from) || "Unknown sender"}</div>
              <div className="text-xs text-slate-500">{customer ? s(customer.company) + " · " : ""}{s(ticket.from) || (customer ? s(customer.email) : "")}</div>
            </div>
          </div>
          <div className="flex items-center gap-2">
            {agent ? (
              <span className="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-medium text-slate-600">Assigned · {s(agent.name)}</span>
            ) : (
              <span className="rounded-full bg-amber-50 px-2.5 py-1 text-xs font-medium text-amber-700">Unassigned</span>
            )}
            {meAgent && s(ticket.assignee_id) !== meAgent && (
              <motion.button whileTap={{ scale: 0.94 }} onClick={assignMe} className="flex items-center gap-1 rounded-xl bg-sky-500 px-3 py-1.5 text-xs font-semibold text-white shadow-md shadow-sky-500/30">
                <UserCheck size={14} /> Assign to me
              </motion.button>
            )}
          </div>
        </div>
        <LayoutGroup id={"flow" + id}>
          <div className="mt-4 grid grid-cols-4 gap-1 rounded-xl bg-slate-100 p-1">
            {FLOW.map((k) => (
              <button key={k} onClick={() => setStatus(k)} className="relative rounded-lg py-1.5 text-xs font-semibold capitalize">
                {status === k && <motion.span layoutId="flowpill" className={"absolute inset-0 rounded-lg shadow-sm " + ST[k]} transition={{ type: "spring", stiffness: 500, damping: 36 }} />}
                <span className={"relative " + (status === k ? "text-white" : "text-slate-500")}>{k}</span>
              </button>
            ))}
          </div>
        </LayoutGroup>
      </div>

      <div className="min-h-[260px] flex-1 space-y-3 overflow-y-auto bg-slate-50/60 p-4 sm:p-5">
        <Msg role="customer" name={customer ? s(customer.name) : s(ticket.from) || "Customer"} body={s(ticket.body)} time={ago(s(ticket.created_at), now)} i={0} />
        <AnimatePresence initial={false}>
          {thread.map((m, i) => (
            <Msg key={s(m.kind) + s(m.id)} role={m.kind === "note" ? "note" : s(m.author_role)} name={s(m.author_name)} body={s(m.body)} time={ago(s(m.at) || s(m.created_at), now)} i={i + 1} />
          ))}
        </AnimatePresence>
        {status === "solved" && s(ticket.csat) !== "" && (
          <div className="rounded-xl bg-emerald-50 px-4 py-3 text-sm text-emerald-800">CSAT {s(ticket.csat)}/5{s(ticket.csat_comment) ? " — “" + s(ticket.csat_comment) + "”" : ""}</div>
        )}
      </div>

      <div className={"border-t p-3 transition-colors sm:p-4 " + (mode === "note" ? "border-amber-200 bg-amber-50/70" : "border-slate-100 bg-white")}>
        <div className="mb-2 flex items-center justify-between">
          <div className="flex gap-1 rounded-lg bg-slate-100 p-0.5">
            {(["reply", "note"] as const).map((k) => (
              <button key={k} onClick={() => setMode(k)} className={"flex items-center gap-1 rounded-md px-3 py-1 text-xs font-semibold " + (mode === k ? (k === "note" ? "bg-amber-400 text-amber-950 shadow-sm" : "bg-white text-slate-900 shadow-sm") : "text-slate-500")}>
                {k === "note" && <FileText size={12} />}
                {k === "reply" ? "Reply" : "Internal note"}
              </button>
            ))}
          </div>
          <button onClick={suggest} disabled={suggesting} className="flex items-center gap-1 rounded-lg bg-sky-50 px-2.5 py-1 text-xs font-semibold text-sky-700 disabled:opacity-50">
            <Sparkles size={13} className={suggesting ? "animate-spin" : ""} /> {suggesting ? "Writing…" : "Suggest reply"}
          </button>
        </div>
        <div className="flex items-end gap-2">
          <textarea aria-label={mode === "note" ? "Internal note" : "Reply"} value={text} onChange={(e) => setText(e.target.value)} rows={mode === "reply" && text.length > 120 ? 5 : 2} placeholder={mode === "note" ? "Only your team can see this…" : "Reply to the customer…"} className="max-h-48 flex-1 resize-none rounded-xl border border-slate-200 bg-white px-3.5 py-2.5 text-[14px] outline-none focus:border-sky-400" />
          <motion.button whileTap={reduce ? undefined : { scale: 0.9 }} onClick={send} disabled={busy || !text.trim()} aria-label="Send" className={"grid h-11 w-11 shrink-0 place-items-center rounded-xl text-white shadow-md disabled:opacity-40 " + (mode === "note" ? "bg-amber-500" : "bg-sky-500 shadow-sky-500/30")}>
            <Send size={18} />
          </motion.button>
        </div>
      </div>
    </div>
  );
}

function Msg({ role, name, body, time, i }: { role: string; name: string; body: string; time: string; i: number }) {
  const reduce = useReducedMotion();
  const agentSide = role === "agent" || role === "note";
  const cls =
    role === "note"
      ? "border border-dashed border-amber-300 bg-amber-50 text-amber-950"
      : role === "agent"
      ? "bg-sky-500 text-white rounded-br-md"
      : "border border-slate-200 bg-white rounded-bl-md";
  return (
    <motion.div
      layout={!reduce}
      initial={reduce ? false : { opacity: 0, y: 12, scale: 0.97 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      transition={{ type: "spring", stiffness: 320, damping: 26, delay: reduce ? 0 : Math.min(i, 6) * 0.03 }}
      className={"flex " + (agentSide ? "justify-end" : "justify-start")}
    >
      <div className={"max-w-[88%] rounded-2xl px-4 py-2.5 shadow-sm " + cls}>
        <div className={"mb-0.5 flex items-center gap-1.5 text-[11px] font-semibold " + (role === "agent" ? "text-sky-100" : role === "note" ? "text-amber-700" : "text-sky-600")}>
          {role === "note" && <FileText size={11} />}
          {name}
          {role === "note" && " · internal"}
        </div>
        <div className="whitespace-pre-wrap text-[14px] leading-relaxed">{body}</div>
        <div className={"mt-1 text-right text-[10px] " + (role === "agent" ? "text-sky-100" : "text-slate-400")}>{time}</div>
      </div>
    </motion.div>
  );
}

import { useEffect, useMemo, useState } from "react";
import type { ReactNode } from "react";
import { motion, animate, useReducedMotion } from "motion/react";
import { Ticket, Inbox, LayoutDashboard, LogOut, Star, AlertTriangle, CheckCircle, Activity, Flame } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

type R = Record<string, unknown>;
type Props = { app?: AppHandle };

const s = (v: unknown) => (v == null ? "" : String(v));
const STATUSES = [
  { k: "new", c: "#0EA5E9", l: "New" },
  { k: "open", c: "#6366F1", l: "Open" },
  { k: "pending", c: "#F59E0B", l: "Pending" },
  { k: "solved", c: "#10B981", l: "Solved" },
];
const PRIS = [
  { k: "urgent", c: "#F43F5E", l: "Urgent" },
  { k: "high", c: "#F97316", l: "High" },
  { k: "normal", c: "#0EA5E9", l: "Normal" },
  { k: "low", c: "#94A3B8", l: "Low" },
];

function Counter({ value, decimals = 0, suffix = "" }: { value: number; decimals?: number; suffix?: string }) {
  const reduce = useReducedMotion();
  const [v, setV] = useState(reduce ? value : 0);
  useEffect(() => {
    if (reduce) {
      setV(value);
      return;
    }
    const c = animate(0, value, { duration: 1.1, ease: [0.16, 1, 0.3, 1], onUpdate: (x) => setV(x) });
    return () => c.stop();
  }, [value, reduce]);
  return (
    <span className="tabular-nums">
      {v.toFixed(decimals)}
      {suffix}
    </span>
  );
}

function Card({ children, className = "", i = 0 }: { children: ReactNode; className?: string; i?: number }) {
  const reduce = useReducedMotion();
  return (
    <motion.div
      initial={reduce ? false : { opacity: 0, y: 18 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ type: "spring", stiffness: 220, damping: 26, delay: reduce ? 0 : i * 0.06 }}
      className={"rounded-3xl border border-slate-200 bg-white p-5 shadow-[0_1px_2px_rgba(15,23,42,0.04),0_12px_32px_-16px_rgba(15,23,42,0.14)] " + className}
    >
      {children}
    </motion.div>
  );
}

function Donut({ parts, total }: { parts: { c: string; v: number }[]; total: number }) {
  const reduce = useReducedMotion();
  const r = 52;
  const C = 2 * Math.PI * r;
  let acc = 0;
  return (
    <svg viewBox="0 0 140 140" className="h-40 w-40 -rotate-90">
      <circle cx="70" cy="70" r={r} fill="none" stroke="#F1F5F9" strokeWidth="16" />
      {total > 0 &&
        parts.map((p, i) => {
          const len = (p.v / total) * C;
          const off = acc;
          acc += len;
          return (
            <motion.circle
              key={i}
              cx="70"
              cy="70"
              r={r}
              fill="none"
              stroke={p.c}
              strokeWidth="16"
              strokeLinecap="butt"
              strokeDashoffset={-off}
              initial={reduce ? false : { strokeDasharray: "0 " + C }}
              animate={{ strokeDasharray: Math.max(len - 2, 0) + " " + C }}
              transition={{ duration: 0.9, delay: 0.2 + i * 0.1, ease: "easeOut" }}
            />
          );
        })}
    </svg>
  );
}

export default function LeadDashboard({ app }: Props) {
  const reduce = useReducedMotion();
  const [now, setNow] = useState(0);
  useEffect(() => {
    setNow(Date.now());
    const t = setInterval(() => setNow(Date.now()), 30000);
    return () => clearInterval(t);
  }, []);
  useEffect(() => (app ? app.live("ticket") : undefined), [app]);

  const tickets: R[] = app ? (app.rows("ticket") as R[]) : [];
  const agents: R[] = app ? (app.rows("agent") as R[]) : [];
  const loading = app ? app.loading("ticket") : false;

  const d = useMemo(() => {
    const byStatus = STATUSES.map((x) => ({ ...x, v: tickets.filter((t) => (s(t.status) || "new") === x.k).length }));
    const byPri = PRIS.map((x) => ({ ...x, v: tickets.filter((t) => (s(t.priority) || "normal") === x.k && s(t.status) !== "solved").length }));
    const openList = tickets.filter((t) => s(t.status) !== "solved");
    const breached = openList
      .filter((t) => t.escalated === true || (s(t.sla_due) && new Date(s(t.sla_due)).getTime() < now))
      .sort((a, b) => s(a.sla_due).localeCompare(s(b.sla_due)));
    const rated = tickets.filter((t) => Number(t.csat) > 0);
    const avg = rated.length ? rated.reduce((a, t) => a + Number(t.csat), 0) / rated.length : 0;
    const dist = [5, 4, 3, 2, 1].map((n) => ({ n, v: rated.filter((t) => Number(t.csat) === n).length }));
    const solvedPct = tickets.length ? (byStatus[3].v / tickets.length) * 100 : 0;
    const load = agents.map((a) => ({
      name: s(a.name),
      v: openList.filter((t) => s(t.assignee_id) === s(a.id)).length,
      done: tickets.filter((t) => s(t.assignee_id) === s(a.id) && s(t.status) === "solved").length,
    }));
    return { byStatus, byPri, openList, breached, rated, avg, dist, solvedPct, load };
  }, [tickets, agents, now]);

  const maxStatus = Math.max(1, ...d.byStatus.map((x) => x.v));
  const maxDist = Math.max(1, ...d.dist.map((x) => x.v));
  const maxLoad = Math.max(1, ...d.load.map((x) => x.v + x.done));
  const priTotal = d.byPri.reduce((a, x) => a + x.v, 0);
  const lead = s(app?.user.name).split(" ")[0] || "there";

  const navItem = (on: boolean) => "grid h-11 w-11 place-items-center rounded-xl transition-colors " + (on ? "bg-sky-500 text-white shadow-lg shadow-sky-500/40" : "text-slate-400 hover:bg-white/10 hover:text-white");

  const kpis = [
    { l: "Open tickets", v: d.openList.length, icon: Inbox, tone: "bg-sky-50 text-sky-600", dec: 0, suf: "" },
    { l: "SLA breaches", v: d.breached.length, icon: AlertTriangle, tone: "bg-rose-50 text-rose-600", dec: 0, suf: "" },
    { l: "CSAT average", v: d.avg, icon: Star, tone: "bg-amber-50 text-amber-600", dec: 1, suf: " / 5" },
    { l: "Resolved", v: d.solvedPct, icon: CheckCircle, tone: "bg-emerald-50 text-emerald-600", dec: 0, suf: "%" },
  ];

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 lg:pl-[68px] [&_h1]:!font-sans [&_h2]:!font-sans [&_h3]:!font-sans">
      <aside className="fixed inset-y-0 left-0 z-30 hidden w-[68px] flex-col items-center gap-2 bg-slate-950 py-4 lg:flex">
        <div className="mb-4 grid h-10 w-10 place-items-center rounded-xl bg-sky-500 text-white">
          <Ticket size={20} />
        </div>
        <button aria-label="Queue" title="Queue" onClick={() => app?.navigate("/inbox")} className={navItem(false)}>
          <Inbox size={20} />
        </button>
        <button aria-label="Dashboard" title="Dashboard" onClick={() => app?.navigate("/dashboard")} className={navItem(true)}>
          <LayoutDashboard size={20} />
        </button>
        <div className="flex-1" />
        <button aria-label="Sign out" title="Sign out" onClick={() => app?.auth.signOut()} className={navItem(false)}>
          <LogOut size={19} />
        </button>
      </aside>
      <header className="sticky top-0 z-30 flex h-14 items-center justify-between border-b border-slate-200 bg-white/90 px-4 backdrop-blur-xl lg:hidden">
        <div className="flex items-center gap-2 font-bold tracking-tight">
          <span className="grid h-8 w-8 place-items-center rounded-lg bg-sky-500 text-white">
            <Ticket size={17} />
          </span>
          Relay
        </div>
        <div className="flex items-center gap-1">
          <button aria-label="Queue" onClick={() => app?.navigate("/inbox")} className="grid h-9 w-9 place-items-center rounded-lg text-slate-500">
            <Inbox size={18} />
          </button>
          <button aria-label="Dashboard" className="grid h-9 w-9 place-items-center rounded-lg bg-sky-50 text-sky-600">
            <LayoutDashboard size={18} />
          </button>
          <button aria-label="Sign out" onClick={() => app?.auth.signOut()} className="grid h-9 w-9 place-items-center rounded-lg text-slate-500">
            <LogOut size={17} />
          </button>
        </div>
      </header>

      <main className="mx-auto max-w-[1300px] px-4 pb-16 pt-6 lg:px-8">
        <motion.div initial={reduce ? false : { opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="mb-6">
          <div className="text-sm font-medium text-sky-600">Team overview</div>
          <h1 className="font-sans text-2xl font-bold tracking-tight sm:text-3xl">Good to see you, {lead}</h1>
          <p className="text-slate-500">How the desk is performing against its promises right now.</p>
        </motion.div>

        {loading && tickets.length === 0 ? (
          <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
            {[0, 1, 2, 3].map((i) => (
              <div key={i} className="h-28 animate-pulse rounded-3xl bg-slate-200/70" />
            ))}
          </div>
        ) : (
          <div className="grid grid-cols-2 gap-3 lg:grid-cols-4 lg:gap-4">
            {kpis.map((k, i) => (
              <Card key={k.l} i={i} className="!p-4 sm:!p-5">
                <div className={"mb-3 grid h-9 w-9 place-items-center rounded-xl " + k.tone}>
                  <k.icon size={18} />
                </div>
                <div className="text-2xl font-bold tracking-tight sm:text-3xl">
                  <Counter value={k.v} decimals={k.dec} suffix={k.suf} />
                </div>
                <div className="text-sm text-slate-500">{k.l}</div>
              </Card>
            ))}
          </div>
        )}

        <div className="mt-4 grid gap-4 lg:mt-5 lg:grid-cols-3 lg:gap-5">
          <Card i={4} className="lg:col-span-2">
            <div className="mb-4 flex items-center justify-between">
              <h3 className="flex items-center gap-2 font-sans font-semibold">
                <Activity size={17} className="text-sky-500" /> Tickets by status
              </h3>
              <span className="text-xs text-slate-400">{tickets.length} total</span>
            </div>
            <div className="flex h-48 items-end gap-3 sm:gap-6">
              {d.byStatus.map((x, i) => (
                <div key={x.k} className="flex h-full flex-1 flex-col items-center justify-end">
                  <div className="mb-1.5 text-sm font-bold tabular-nums">{x.v}</div>
                  <motion.div
                    className="w-full max-w-[84px] rounded-t-2xl"
                    style={{ background: "linear-gradient(180deg," + x.c + "," + x.c + "bb)" }}
                    initial={reduce ? false : { height: 0 }}
                    animate={{ height: Math.max((x.v / maxStatus) * 150, 6) }}
                    transition={{ type: "spring", stiffness: 120, damping: 18, delay: 0.25 + i * 0.1 }}
                  />
                  <div className="mt-2 text-xs font-medium text-slate-500">{x.l}</div>
                </div>
              ))}
            </div>
          </Card>

          <Card i={5}>
            <h3 className="mb-2 flex items-center gap-2 font-sans font-semibold">
              <Flame size={17} className="text-orange-500" /> Open by priority
            </h3>
            <div className="flex items-center gap-4">
              <div className="relative shrink-0">
                <Donut parts={d.byPri.map((x) => ({ c: x.c, v: x.v }))} total={priTotal} />
                <div className="absolute inset-0 grid place-items-center">
                  <div className="text-center">
                    <div className="text-2xl font-bold">
                      <Counter value={priTotal} />
                    </div>
                    <div className="text-[11px] text-slate-400">open</div>
                  </div>
                </div>
              </div>
              <div className="flex-1 space-y-2">
                {d.byPri.map((x) => (
                  <div key={x.k} className="flex items-center justify-between text-sm">
                    <span className="flex items-center gap-2 text-slate-600">
                      <span className="h-2.5 w-2.5 rounded-full" style={{ background: x.c }} />
                      {x.l}
                    </span>
                    <span className="font-semibold tabular-nums">{x.v}</span>
                  </div>
                ))}
              </div>
            </div>
          </Card>

          <Card i={6}>
            <h3 className="mb-4 flex items-center gap-2 font-sans font-semibold">
              <Star size={17} className="text-amber-500" /> Customer satisfaction
            </h3>
            <div className="mb-4 flex items-center gap-4">
              <div className="text-5xl font-bold tracking-tight">
                <Counter value={d.avg} decimals={1} />
              </div>
              <div>
                <div className="flex">
                  {[1, 2, 3, 4, 5].map((n, i) => (
                    <motion.span key={n} initial={reduce ? false : { scale: 0, rotate: -30 }} animate={{ scale: 1, rotate: 0 }} transition={{ type: "spring", stiffness: 300, damping: 14, delay: 0.4 + i * 0.07 }}>
                      <Star size={20} className={n <= Math.round(d.avg) ? "fill-amber-400 text-amber-400" : "text-slate-300"} />
                    </motion.span>
                  ))}
                </div>
                <div className="text-xs text-slate-500">{d.rated.length} ratings</div>
              </div>
            </div>
            <div className="space-y-1.5">
              {d.dist.map((x, i) => (
                <div key={x.n} className="flex items-center gap-2 text-xs">
                  <span className="w-3 text-slate-500">{x.n}</span>
                  <div className="h-2 flex-1 overflow-hidden rounded-full bg-slate-100">
                    <motion.div className="h-full rounded-full bg-amber-400" initial={reduce ? false : { width: 0 }} animate={{ width: (x.v / maxDist) * 100 + "%" }} transition={{ duration: 0.8, delay: 0.4 + i * 0.08 }} />
                  </div>
                  <span className="w-4 text-right tabular-nums text-slate-500">{x.v}</span>
                </div>
              ))}
            </div>
          </Card>

          <Card i={7}>
            <h3 className="mb-4 font-sans font-semibold">Agent workload</h3>
            <div className="space-y-4">
              {d.load.length === 0 && <div className="text-sm text-slate-400">No agents yet</div>}
              {d.load.map((a, i) => (
                <div key={a.name}>
                  <div className="mb-1.5 flex items-center justify-between text-sm">
                    <span className="font-medium">{a.name}</span>
                    <span className="text-xs text-slate-500">{a.v} open · {a.done} solved</span>
                  </div>
                  <div className="flex h-2.5 overflow-hidden rounded-full bg-slate-100">
                    <motion.div className="h-full bg-sky-500" initial={reduce ? false : { width: 0 }} animate={{ width: (a.v / maxLoad) * 100 + "%" }} transition={{ duration: 0.8, delay: 0.4 + i * 0.1 }} />
                    <motion.div className="h-full bg-emerald-400" initial={reduce ? false : { width: 0 }} animate={{ width: (a.done / maxLoad) * 100 + "%" }} transition={{ duration: 0.8, delay: 0.5 + i * 0.1 }} />
                  </div>
                </div>
              ))}
            </div>
          </Card>

          <Card i={8}>
            <div className="mb-3 flex items-center justify-between">
              <h3 className="flex items-center gap-2 font-sans font-semibold">
                <AlertTriangle size={17} className="text-rose-500" /> SLA breaches
              </h3>
              <span className="rounded-full bg-rose-50 px-2 py-0.5 text-xs font-bold text-rose-600">{d.breached.length}</span>
            </div>
            <div className="space-y-2">
              {d.breached.length === 0 && (
                <div className="rounded-2xl bg-emerald-50 p-4 text-center text-sm text-emerald-700">
                  <CheckCircle className="mx-auto mb-1" size={22} /> Every ticket is within SLA
                </div>
              )}
              {d.breached.slice(0, 5).map((t, i) => {
                const late = now - new Date(s(t.sla_due)).getTime();
                const hrs = Math.max(1, Math.round(late / 3600000));
                return (
                  <motion.button
                    key={s(t.id)}
                    initial={reduce ? false : { opacity: 0, x: -16 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ delay: 0.5 + i * 0.07 }}
                    whileTap={{ scale: 0.98 }}
                    onClick={() => app?.navigate("/inbox")}
                    className="flex w-full items-center justify-between gap-3 rounded-xl border border-rose-100 bg-rose-50/50 px-3 py-2 text-left"
                  >
                    <span className="line-clamp-1 text-sm font-medium">{s(t.subject)}</span>
                    <span className="shrink-0 text-xs font-bold text-rose-600">{late > 0 ? "+" + hrs + "h" : "Escalated"}</span>
                  </motion.button>
                );
              })}
            </div>
          </Card>
        </div>
      </main>
    </div>
  );
}

